  iframeWrite(iframe, html) {
    let doc = iframe.contentDocument;
    const parser = new DOMParser();
    const parsedDoc = parser.parseFromString(html, 'text/html');
    const htmlHead = parsedDoc.head.innerHTML;
    const htmlBody = parsedDoc.body.innerHTML;
    const bodyClass = parsedDoc.body.getAttribute('class');
    let range = doc.createRange();
    doc.head.innerHTML = '';
    doc.head.appendChild(range.createContextualFragment(htmlHead));
    doc.body.setAttribute('class', bodyClass);
    doc.body.innerHTML = '';
    doc.body.appendChild(range.createContextualFragment(htmlBody));
  }

