    const overlayVideo = activeBox.querySelector('.is-video-bg');
    const overlayContent = activeBox.querySelector('.is-overlay-content');
    const container = activeBox.querySelector('.is-builder');
    let overlayBgHasContent = false;

    if (overlayBg) {
      let childs = this.builder.editor.dom.elementChildren(overlayBg);
      childs.forEach(item => {
        if (!dom$i.hasClass(item, 'is-overlay-color')) {
          overlayBgHasContent = true;
        }
      });
    } //Show/Hide Tabs & Get current value


    if (!overlayBg) {
      modalEditBox.querySelector('#divBoxPickPhoto').style.display = 'none';
    } else {
      if (this.builder.settings.photoselect == '') {
        modalEditBox.querySelector('#divBoxPickPhoto').style.display = 'none';
      } else {
        modalEditBox.querySelector('#divBoxPickPhoto').style.display = 'block';
      }

      if (overlayBgHasContent) {
        //There is content within background overlay
        modalEditBox.querySelector('#chkAnimateBg').parentNode.parentNode.style.display = 'none';
        modalEditBox.querySelector('#chkParallaxBg').parentNode.parentNode.style.display = 'none';
      } else {
        modalEditBox.querySelector('#chkAnimateBg').parentNode.parentNode.style.display = '';
      }
    }

