    if (vPos === 'top' && hPos === 'left') dom$i.addClass(modalEditBox.querySelector('.cmd-box-content-pos[data-value="topleft"]'), 'on');
    if (vPos === 'top' && hPos === 'center') dom$i.addClass(modalEditBox.querySelector('.cmd-box-content-pos[data-value="topcenter"]'), 'on');
    if (vPos === 'top' && hPos === 'right') dom$i.addClass(modalEditBox.querySelector('.cmd-box-content-pos[data-value="topright"]'), 'on');
    if (vPos === 'middle' && hPos === 'left') dom$i.addClass(modalEditBox.querySelector('.cmd-box-content-pos[data-value="middleleft"]'), 'on');
    if (vPos === 'middle' && hPos === 'center') dom$i.addClass(modalEditBox.querySelector('.cmd-box-content-pos[data-value="middlecenter"]'), 'on');
    if (vPos === 'middle' && hPos === 'right') dom$i.addClass(modalEditBox.querySelector('.cmd-box-content-pos[data-value="middleright"]'), 'on');
    if (vPos === 'bottom' && hPos === 'left') dom$i.addClass(modalEditBox.querySelector('.cmd-box-content-pos[data-value="bottomleft"]'), 'on');
    if (vPos === 'bottom' && hPos === 'center') dom$i.addClass(modalEditBox.querySelector('.cmd-box-content-pos[data-value="bottomcenter"]'), 'on');
    if (vPos === 'bottom' && hPos === 'right') dom$i.addClass(modalEditBox.querySelector('.cmd-box-content-pos[data-value="bottomright"]'), 'on'); // Ex. Slider on overlayContent

