  refreshModule() {
    const modalEditModule = document.querySelector('.is-modal.editmodule');
    const builderStuff = this.builder.builderStuff; // let activeBox = this.builder.activeBox;
    // let activeModule = activeBox.querySelector('.is-overlay-content[data-module]'); 

    let activeModule = this.builder.doc.querySelector('[data-module-active="1"]');
    let modalIframe = modalEditModule.querySelector('iframe');
    if (modalIframe.contentWindow.construct) modalIframe.contentWindow.construct();
    const hidModuleCode = builderStuff.querySelector('#hidModuleCode');
    const hidModuleSettings = builderStuff.querySelector('#hidModuleSettings'); //Save Html (original)

    activeModule.setAttribute('data-html', encodeURIComponent(hidModuleCode.value)); //Save Settings (original)

    activeModule.setAttribute('data-settings', encodeURIComponent(hidModuleSettings.value));
    let html = hidModuleCode.value;
    html = html.replace(/{id}/g, this.uniqueId()); //Render (programmatically)

    let range = document.createRange();
    activeModule.innerHTML = '';
    activeModule.appendChild(range.createContextualFragment(html)); // We use createContextualFragment so that embedded javascript code (code block) will be executed

    this.builder.settings.onRender();
    this.builder.settings.onChange();
  }

  boxImage(url, err) {
    // Remove Waiting Indicator
    const builderStuff = this.builder.builderStuff;
    const indicator = builderStuff.querySelector('.waiting-indicator');
    const indicatorOverlay = builderStuff.querySelector('.waiting-indicator-overlay');
    if (indicator) indicator.parentNode.removeChild(indicator);
    if (indicatorOverlay) indicatorOverlay.parentNode.removeChild(indicatorOverlay);

    if (err) {
      alert(err);
      return;
    }
    /*
    let activeBox;
    if(this.builder.targetBox) {
        activeBox = this.builder.targetBox;
         this.targetBox = null;
    } else {
        activeBox = this.builder.activeBox;
    } 
    */


    let activeBox = this.builder.activeBox;
    this.builder.editor.saveForUndo();
    let overlay = activeBox.querySelector('.is-overlay');

    if (!overlay) {
      activeBox.insertAdjacentHTML('afterbegin', '<div class="is-overlay"></div>');
      overlay = activeBox.querySelector('.is-overlay');
    }

    if (activeBox.classList.contains('is-section')) {
      if (activeBox.classList.contains('min-height-20') || activeBox.classList.contains('min-height-25') || activeBox.classList.contains('min-height-30') || activeBox.classList.contains('min-height-40') || activeBox.classList.contains('min-height-50') || activeBox.classList.contains('min-height-60') || activeBox.classList.contains('min-height-70') || activeBox.classList.contains('min-height-75') || activeBox.classList.contains('min-height-80') || activeBox.classList.contains('min-height-90') || activeBox.classList.contains('min-height-100')) ; else {
        activeBox.classList.add('min-height-60');
      }
    }

    if (url !== '') {
      let overlayBg = overlay.querySelector('.is-overlay-bg');

      if (!overlayBg) {
        overlay.insertAdjacentHTML('beforeend', '<div class="is-overlay-bg"></div>');
        overlayBg = overlay.querySelector('.is-overlay-bg');
      }

      overlayBg.style.backgroundImage = 'url(\'' + url + '\')';
      overlayBg.style.backgroundPosition = 50 + '%' + ' ' + 60 + '%'; //default
      // Reset position & filter (grayscale)

      overlayBg.style.filter = '';
      overlay.style.filter = '';
      overlayBg.style.backgroundSize = '';
      overlayBg.style.backgroundPosition = '50% 60%';
      overlayBg.removeAttribute('data-scale');
      overlayBg.removeAttribute('data-x');
      overlayBg.removeAttribute('data-y');
      overlayBg.style.top = '';
      overlayBg.style.bottom = '';
      overlayBg.style.left = '';
      overlayBg.style.right = '';
      overlayBg.style.width = '';
      overlayBg.style.height = '';
      overlayBg.removeAttribute('data-bg-xs');
      overlayBg.removeAttribute('data-bg-sm');
      overlayBg.removeAttribute('data-bg-md');
      overlayBg.removeAttribute('data-bg-lg'); // /Reset 
    } else {
      let overlayBg = overlay.querySelector('.is-overlay-bg');
      if (overlayBg) overlayBg.parentNode.removeChild(overlayBg);
      let overlayColor = overlay.querySelector('.is-overlay-color');

      if (overlayColor) {
        overlayColor.parentNode.removeChild(overlayColor);
      }

      let overlayContent = overlay.querySelector('.is-overlay-content');

      if (overlayContent) {
        if (overlayContent.innerHTML === '') overlayContent.parentNode.removeChild(overlayContent);
      }

      activeBox.classList.remove('m-overlay-stack');
      activeBox.classList.remove('m-dark-text');
    }

    this.builder.onRender();
    this.builder.onChange();
    if (this.builder.onAssetUpload) this.builder.onAssetUpload(url);
  }

