  /* Serializes the runtime plugin registry for the exported page.
   *
   * The registry is read from the live runtime the host page set up
   * (window.builderRuntime), so an exported page carries exactly the plugins
   * the integrator registered — nothing has to be duplicated in the
   * template. Entries are lazy: the runtime fetches a plugin's script/style
   * only when the content actually uses it.
   *
   * Those URLs are built against the host page's own location, so any URL
   * under that base is rewritten back to a [%PATH%] token and re-resolved
   * against wherever the exported page ends up.
   */
  getPluginRegistry() {
    const win = this.builder.win;
    let plugins;
    try {
      plugins = win.builderRuntime.settings.plugins;
    } catch (e) {/* no runtime on the page */}
    if (!plugins) return '{}';
    let base = '';
    try {
      const href = win.location.href;
      base = href.substring(0, href.lastIndexOf('/'));
    } catch (e) {/* cross-origin content frame */}
    const toToken = url => {
      if (typeof url !== 'string') return url;
      if (base && url.startsWith(base + '/')) return '[%PATH%]' + url.substring(base.length);
      return url;
    };
    const registry = {};
    Object.keys(plugins).forEach(name => {
      const plugin = plugins[name];
      if (!plugin) return;
      const entry = Object.assign({}, plugin);
      if (entry.url) entry.url = toToken(entry.url);
      if (entry.css) entry.css = toToken(entry.css);
      registry[name] = entry;
    });
    return JSON.stringify(registry, null, 4);
  }
  getElementPosition(element) {
    const iframe = this.builder.iframe;
    let top, left;
    let scaleX, scaleY;
    if (this.builder.iframe) {
      let divContentView = document.querySelector('.is-content-view');
      if (!divContentView) divContentView = iframe.parentNode;
      const divContentViewStyles = window.getComputedStyle(divContentView);
      const transform = divContentViewStyles.transform;
      if (transform !== 'none') {
        const matrixValues = transform.match(/matrix\(([0-9., -]+)\)/)[1].split(',');
        scaleX = parseFloat(matrixValues[0]);
        scaleY = parseFloat(matrixValues[3]);
      } else {
        scaleX = 1;
        scaleY = 1;
      }
      const iframeRect = iframe.getBoundingClientRect();
      top = element.getBoundingClientRect().top * scaleY + iframeRect.top;
      left = element.getBoundingClientRect().left * scaleX + iframeRect.left;
    } else {
      top = element.getBoundingClientRect().top;
      left = element.getBoundingClientRect().left;
      scaleX = 1;
      scaleY = 1;
    }
    return {
      top,
      left,
      scaleX,
      scaleY
    };
  }
