/* ----------------------------------------------------------------------
   Clean copy / cut
   ----------------------------------------------------------------------
   On copy the browser bakes an element's COMPUTED appearance into the
   clipboard as inline `style` — including editor-only indicators (e.g. the
   `.elm-active` highlight background) and generic computed props (color,
   text-align, width/height). None of that is in the real content. We
   intercept copy/cut and instead write HTML SERIALIZED FROM THE LIVE SOURCE
   DOM: because we serialize it ourselves, the browser's computed-style
   injection never happens, so AUTHORED inline styles survive while the
   leaks never appear. Editor state classes are stripped. (Cut must
   preventDefault to override the clipboard payload, which also cancels the
   browser's own deletion — so we run Inscribe's clean deleteSelection.) */

// Editor-owned state classes that must never end up in copied content.
const COPY_STATE_CLASSES = ['elm-active', 'cell-active'];
function stripCopyArtifacts(container) {
  const els = container.querySelectorAll('*');
  for (let i = 0; i < els.length; i++) {
    const el = els[i];
    if (el.classList && el.classList.length) {
      for (let j = 0; j < COPY_STATE_CLASSES.length; j++) el.classList.remove(COPY_STATE_CLASSES[j]);
      if (!el.classList.length) el.removeAttribute('class');
    }
    if (el.hasAttribute('contenteditable')) el.removeAttribute('contenteditable');
    if (el.hasAttribute('data-cb-nohighlight')) el.removeAttribute('data-cb-nohighlight');
  }
}

/* Serialize the selection from the live DOM, wrapping in clean shallow
   clones of its ancestors (up to but NOT including `root`) so a
   within-block selection keeps its block (e.g. <h1 class="size-35">…). */
function cleanCopyHTML(root, range, doc) {
  const container = doc.createElement('div');
  container.appendChild(range.cloneContents());
  let node = range.commonAncestorContainer;
  if (node.nodeType === 3) node = node.parentNode; // text -> its element
  while (node && node !== root && node.nodeType === 1) {
    const wrapper = node.cloneNode(false); // keeps class + AUTHORED style attr
    while (container.firstChild) wrapper.appendChild(container.firstChild);
    container.appendChild(wrapper);
    node = node.parentNode;
  }
  stripCopyArtifacts(container);
  return container.innerHTML;
}

