  loadHTML(html) {
    //backward

    this.loadHtml(html);
  }

  // Set the theme body class from a mode ('dark'|'light'|'colored'|'colored-dark'|'').
  // Modes map 1:1 to a class; '' clears them all (the default/white theme). Used by
  // setUIColor for BOTH the css-file path and the token-only path (empty csslink), so
  // a theme whose _tokens.scss bucket carries all its colours needs no css file at all.
  applyThemeClass(mode) {
    const body = document.body;
    ['dark', 'colored', 'colored-dark', 'light'].forEach(c => this.dom.removeClass(body, c));
    if (mode) this.dom.addClass(body, mode);
  }
  async setUIColor(mode, csslink) {
    // Get previous css
    let cssLink = document.querySelector('[data-cb-color]');
    if (cssLink) cssLink.setAttribute('data-cb-del', '');
    // if(cssLink) cssLink.parentNode.removeChild(cssLink);

    // Backward compat: some built-in themes are now token-only (their look comes
    // from the _tokens.scss body.<mode> bucket) and their stylesheet was removed.
    // An old production config may still point at such a file — don't request one
    // that no longer exists; fall through to the token-only path below.
    const retiredThemeCss = ['dark.css'];
    if (csslink && retiredThemeCss.includes(csslink.split('/').pop())) csslink = '';

    // Add new css
    if (csslink) {
      var link = document.createElement('link');
      link.rel = 'stylesheet';
      link.href = csslink;
      link.setAttribute('data-cb-color', '');

      // Runs once the stylesheet settles — on load OR on error. The error path
      // matters for backward compat: if a theme file 404s (e.g. still referenced
      // by an old config), the theme must STILL switch — apply the body class +
      // tokens anyway, otherwise this callback (and the class toggle) never runs.
      let settled = false;
      const onSettled = () => {
        if (settled) return;
        settled = true;
        if (!document.body.contains(this.builderStuff)) return; // in case the instance is destroyed

        // Remove previous css
        cssLink = document.querySelector('[data-cb-del]');
        if (cssLink) cssLink.parentNode.removeChild(cssLink);
        this.applyThemeClass(mode);

        // Css settled. Now we can get UI styles.
        const util = this.util;
        setTimeout(() => {
          util.getUIStyles();
          this.setUIColorRefresh();
          if (this.opts.onThemeChange) this.opts.onThemeChange();
        }, 300);
      };
      link.addEventListener('load', onSettled);
      link.addEventListener('error', onSettled);
      document.head.appendChild(link);
    } else {
      // Remove previous css
      cssLink = document.querySelector('[data-cb-del]');
      if (cssLink) cssLink.parentNode.removeChild(cssLink);

      // Token-only theme (no css file): the body class alone drives the look
      // from the _tokens.scss bucket. Works for ANY mode now, not just ''.
      this.applyThemeClass(mode);

      // Css loaded. Now we can get UI styles.
      const util = this.util;

      // util.getUIStyles();

      // this.setUIColorRefresh();

      // if(this.opts.onThemeChange) this.opts.onThemeChange();

      await this.delay(1000);
      if (!document.body.contains(this.builderStuff)) return; // in case the instance is destroyed

      // setTimeout(()=>{
      util.getUIStyles();
      this.setUIColorRefresh();
      if (this.opts.onThemeChange) this.opts.onThemeChange();
      // }, 1000);
    }
  }

