  async generateImage_Fal(prompt, callback) {
    let modelId;
    let imageSize;
    let outputFormat;
    if (this.imageGenerationSettings) {
      modelId = this.imageGenerationSettings.modelId;
      imageSize = this.imageGenerationSettings.imageSize;
      outputFormat = this.imageGenerationSettings.outputFormat;
    } else {
      modelId = 'fal-ai/flux-1/schnell';
      imageSize = 'landscape_4_3';
      outputFormat = 'jpeg';
    }

    // Construct inputs: model, prompt, size, output format

    let imageModels;
    if (this.imageModels) {
      imageModels = this.imageModels;
    } else if (this.imageGenerationModels) {
      // backward
      imageModels = this.imageGenerationModels;
    } else {
      imageModels = this.codechat.imageModels;
    }
    const modelDef = imageModels.find(m => m.id === modelId) || {};

    // Build options dynamically
    let options = {};

    // Handle size/aspect_ratio if model has sizes
    if (modelDef && modelDef.sizes !== undefined) {
      if (modelDef.sizes !== null && modelDef.sizes.length !== 0) {
        const sizeParam = modelDef.size_param || 'image_size'; // default
        options[sizeParam] = imageSize;
      }
      // if sizes = [] => no size options => exclude size.
    } else {
      // if sizes not defined, use default set
      options['image_size'] = imageSize;
    }

    // Handle output_format if present
    if (outputFormat) {
      const outputParam = modelDef.output_param || 'output_format'; // default
      options[outputParam] = outputFormat;
    }
    // if output_format not defined, exclude output_format.

    this.controller = new AbortController();
    this.signal = this.controller.signal;
    let jsonBody = {
      model: modelId,
      customData: this.customData,
      endpoint: `https://queue.fal.run/${modelId}`,
      payload: {
        prompt,
        ...options
      }
    };
    try {
      let url = this.generateMediaUrl_Fal;
      let headers = {
        ...this.headers,
        ...this.defaultHeaders
      };
      const response = await fetch(url, {
        signal: this.signal,
        method: 'POST',
        headers,
        body: JSON.stringify(jsonBody)
      });
      const result = await response.json();
      if (result.error) {
        console.error(result.error);
        return;
      }
      let requestId = result.request_id;
      const getStatusEndpoint = (model, requestId) => {
        let endpoint = 'https://queue.fal.run/{MODEL}/requests/{REQUEST_ID}/status';
        endpoint = endpoint.replace('{REQUEST_ID}', requestId);
        let firstTwoParts = model.split('/').slice(0, 2).join('/');
        endpoint = endpoint.replace('{MODEL}', firstTwoParts);
        return endpoint;
      };
      const statusEndpoint = getStatusEndpoint(modelId, requestId);
      let inputCheckStatus = {
        model: modelId,
        endpoint: statusEndpoint,
        request_id: requestId,
        customData: this.customData
      };
      let status;
      do {
        const response = await fetch(this.checkRequestStatusUrl_Fal, {
          signal: this.signal,
          method: 'POST',
          headers,
          body: JSON.stringify(inputCheckStatus)
        });
        const result = await response.json();
        if (result.ok && result.status) {
          // From endpoint that uses SDK
          status = result.status;
        } else if (result.data) {
          // From endpoint that uses API
          let data = result.data;
          if (data.image || data.audio || data.audio_file || data.video) {
            status = 'COMPLETED';
          } else if (data.detail && typeof data.detail === 'string' && data.detail.startsWith('Request is still in progress')) {
            //Request is still in progress
            status = 'IN_PROGRESS';
          } else if (data.status && !data.error) {
            status = data.status;
          }
        }
        if (!status) {
          // const message = result.error || (result.data && JSON.stringify(result.data)) || this.out('Request failed.');
          // console.log(message);
          return;
        }
        if (status !== 'COMPLETED') {
          await new Promise(resolve => setTimeout(resolve, 5000)); // Wait before retrying
        }
      } while (status !== 'COMPLETED');
      if (status === 'COMPLETED') {
        const mediaResult = await this.waitingResultFal(jsonBody, requestId);
        if (mediaResult.output && mediaResult.output.length === 1) {
          let imageUrl = mediaResult.output[0];
          callback(imageUrl);
        }
      }
    } catch (error) {
      console.error('Error:', error);
    }
  }
