  setVisibility(s, target) {
    let section = this.builder.activeSection;
    section.classList.remove('hideonmobile'); // remove old

    this.builder.editor.saveForUndo();

    if (s === 'on') {
      if (target === 'xs') {
        section.classList.remove('xs-hidden');
      } else if (target === 'sm') {
        section.classList.remove('sm-hidden');
      } else if (target === 'md') {
        section.classList.remove('md-hidden');
      } else if (target === '') {
        section.classList.remove('desktop-hidden');
      }
    } else {
      // hide
      if (target === 'xs') {
        section.classList.add('xs-hidden');
      } else if (target === 'sm') {
        section.classList.add('sm-hidden'); // hide all others smaller than tablet portrait

        section.classList.add('xs-hidden');
      } else if (target === 'md') {
        section.classList.add('md-hidden'); // hide all others smaller than tablet landscape

        section.classList.add('sm-hidden');
        section.classList.add('xs-hidden');
      } else if (target === '') {
        section.classList.add('desktop-hidden'); // hide all others smaller than desktop

        section.classList.add('md-hidden');
        section.classList.add('sm-hidden');
        section.classList.add('xs-hidden');
      }
    }

    this.builder.onChange();
  }

