    this.native = opts.native !== false; // Legacy conversions (extraction fallback + image transcode)

    this.convertAttachments = opts.convertAttachments === true;

    this.modelCapability = opts.modelCapability || (() => null);

    this.acceptOverride = opts.accept || ''; // Two independent reasons the attach button can be off: a send is in
    // flight, and the model takes no files at all. Tracked separately so
    // one does not clear the other when it lifts.

    this.disabledBySend = false;
    this.noFileSupport = false;
    this.maxImageDimension = opts.maxImageDimension || 1568;
    this.maxFileBytes = opts.maxFileBytes || 20 * 1024 * 1024; // 20 MB

    this.onChange = opts.onChange || (() => {});

    this.onNotice = opts.onNotice || (msg => console.warn(msg)); // user-visible file feedback
    // Whether files can be attached at all


    this.enabled = opts.enabled !== false;
    this.items = [];
    const out = this.out; // --- hidden file input ---

    this.fileInput = document.createElement('input');
    this.fileInput.type = 'file';
    this.fileInput.multiple = true;
    this.fileInput.style.display = 'none';
    this.updatePickerAccept();
    opts.inputArea.appendChild(this.fileInput); // --- attach button (sits in the input wrapper, before the send button) ---

    if (this.enabled) {
      this.attachButton = document.createElement('button');
      this.attachButton.type = 'button';
      this.attachButton.className = 'attach-button';
      this.attachButton.setAttribute('aria-label', out('Attach a file'));
      this.attachButton.title = out('Attach a file');
      this.attachButton.innerHTML = ATTACH_ICON;
      this.applyAttachAvailability();
      opts.inputWrapper.insertBefore(this.attachButton, opts.anchorButton || null);
    } // --- chips container (above the input wrapper) ---


    this.chips = document.createElement('div');
    this.chips.className = 'attachment-chips';
    opts.inputArea.insertBefore(this.chips, opts.inputArea.firstChild); // --- listeners ---

    if (!this.enabled) return;
    this.attachButton.addEventListener('click', () => this.fileInput.click());
    this.fileInput.addEventListener('change', e => {
      this.addFiles(e.target.files);
      this.fileInput.value = ''; // allow re-selecting the same file
    });

