          if (accepts.includes('pdf')) parts.push('application/pdf,.pdf');
          if (accepts.includes('text')) parts.push(TEXT_EXTENSIONS.map(e => '.' + e).join(','));
          if (accepts.includes('office')) parts.push(OFFICE_ZIP_EXTENSIONS.map(e => '.' + e).join(','));
