  /**
   * ============================================================================
   * STREAMING CHAT EXECUTION
   * ============================================================================
   * Handles real-time streaming of chat responses with typing effect
   */


  async executeStreamingChat(question, system) {
    const out = s => this.out(s); // Check if streaming is available


    const hasStreaming = !!this.builder.sendCommandStreamUrl;

    if (!hasStreaming) {
      // Fall back to non-streaming
      return await this.executeNonStreamingChat(question, system);
    } // Create a new streaming message container


    const messageId = 'stream-' + Date.now();
    const messageDiv = document.createElement('div');
    messageDiv.id = messageId;
    messageDiv.className = 'message assistant';
    messageDiv.innerHTML = `
            <div class="message-header">${out('Assistant')}</div>
            <div class="message-content streaming"></div>
        `;
    this.messagesContainer.appendChild(messageDiv);
    this.messagesContainer.scrollTop = this.messagesContainer.scrollHeight;
    const contentDiv = messageDiv.querySelector('.message-content'); // Variables for streaming

    let rawText = ''; // Accumulates all text from stream

    let displayedText = ''; // Text currently displayed (for typing effect)

    let typingQueue = []; // Queue of chunks to type

    let isTyping = false; // Flag to prevent concurrent typing
    // Typing effect function

    const typeNextChunk = async () => {
      if (isTyping || typingQueue.length === 0) return;
      isTyping = true;
      const chunk = typingQueue.shift(); // Type character by character

      for (let char of chunk) {
        displayedText += char; // Render markdown progressively

        const htmlContent = this.renderMarkdown(displayedText);
        contentDiv.innerHTML = htmlContent; // Scroll to bottom

        this.messagesContainer.scrollTop = this.messagesContainer.scrollHeight; // Small delay for typing effect (adjust for speed)

        await new Promise(resolve => setTimeout(resolve, 20));
      }

      isTyping = false; // Continue typing if more chunks are queued

      if (typingQueue.length > 0) {
        typeNextChunk();
      }
    };

    try {
      // Initialize abort controller for this stream
      this.streamController = new AbortController();
      let headers = { ...this.builder.headers,
        ...this.builder.defaultHeaders
      };
      const response = await fetch(this.builder.sendCommandStreamUrl, {
        signal: this.streamController.signal,
        method: 'POST',
        headers,
        body: JSON.stringify({
          question,
          context: '',
          system,
          functs: [],
          temperature: 0.7,
          topP: 0.9,
          num: 1,
          model: this.settings.chatModel // ⭐ USE SELECTED MODEL

        })
      });

      if (!response.ok) {
        throw new Error(`Stream error: ${response.statusText}`);
      } // Read the stream


      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';
      let done = false;

      while (!done) {
        const {
          done: isDone,
          value
        } = await reader.read();
        done = isDone;
        if (done) break;
        const chunk = decoder.decode(value, {
          stream: true
        });
        buffer += chunk;
        const lines = buffer.split('\n');
        buffer = '';

        for (const line of lines) {
          if (line.trim() === '') continue;

          if (line.startsWith('data:')) {
            const payload = line.slice(5).trim();

            if (payload === '[DONE]') {
              // console.log('Stream completed.');
              break;
            }

            try {
              const json = JSON.parse(payload);

              if (json.choices && json.choices[0].delta && json.choices[0].delta.content) {
                const text = json.choices[0].delta.content;
                rawText += text; // Add to typing queue

                typingQueue.push(text); // Start typing if not already typing

                if (!isTyping) {
                  typeNextChunk();
                }
              }
            } catch (error) {
              buffer += line + '\n';
            }
          }
        }
      } // Wait for all typing to complete


      while (typingQueue.length > 0 || isTyping) {
        await new Promise(resolve => setTimeout(resolve, 50));
      } // // Remove streaming cursor
      // contentDiv.classList.remove('streaming');
      // return rawText;
      // Remove streaming cursor


      contentDiv.classList.remove('streaming'); // Add copy button after streaming is complete

      const copyButton = document.createElement('button');
      copyButton.className = 'copy-button';
      copyButton.type = 'button';
      copyButton.setAttribute('aria-label', out('Copy message'));
      copyButton.textContent = out('Copy');
      contentDiv.appendChild(copyButton); // Add copy functionality

      copyButton.addEventListener('click', () => {
        navigator.clipboard.writeText(rawText).then(() => {
          copyButton.textContent = out('Copied!');
          copyButton.classList.add('copied');
          setTimeout(() => {
            copyButton.textContent = out('Copy');
            copyButton.classList.remove('copied');
          }, 2000);
        }).catch(err => {
          console.error(out('Failed to copy:'), err);
        });
      });
      return rawText;
    } catch (error) {
      if (error.name === 'AbortError') {
        // console.log('Stream aborted by user.');
        contentDiv.innerHTML = '<em>' + out('Stream cancelled') + '</em>';
      } else {
        console.error('Stream error:', error);
        throw error;
      }

      return '';
    }
  }
