    if (!el.classList.contains('border-current')) return;
    if ([...el.classList].some(c => c.startsWith('hover:border-'))) return;
    const hover = (el.getAttribute('data-cb-hover') || '').split(/\s+/);
    if (hover.includes('border')) return;
