        this.addSpace();
        let tools = wrapper.querySelectorAll('.is-section-tool');
        tools.forEach(elm => {
          elm.removeAttribute('data-section-active');
        });
        tools = wrapper.querySelectorAll('.is-box-tool');
        tools.forEach(elm => {
          elm.removeAttribute('data-box-active');
        });
        tools = wrapper.querySelectorAll('.is-box-info');
        tools.forEach(elm => {
          elm.removeAttribute('data-boxinfo-active');
        });
        this.rePositionTool();
        this.wrapperEl.style.transition = '';
        this.refreshAnim();
